1	/**
2	 * Server-side run store. Owns the candidate list and the simulation queue so
3	 * state survives a page refresh, and so swapping the local heuristic solver for
4	 * openEMS / the Devin session is a change confined to this file.
5	 */
6	import { phoneV1 } from "./device";
7	import { generateCandidates, isolationDb, scorePoint, simulate } from "./rf";
8	import type {
9	  AgentMessage,
10	  BandRequirement,
11	  Candidate,
12	  DeviceSpec,
13	  Job,
14	  SimResult,
15	} from "./types";
16	
17	const PLANNING_MS = 1600;
18	const PER_JOB_MS = 1500;
19	const CONCURRENCY = 3;
20	
21	interface Run {
22	  id: string;
23	  prompt: string;
24	  bandIds: string[];
25	  createdAt: number;
26	  spec: DeviceSpec;
27	  candidates: Candidate[];
28	  queue: Candidate[];
29	}
30	
31	const runs = new Map<string, Run>();
32	const resultCache = new Map<string, SimResult>();
33	
34	function bandById(spec: DeviceSpec, id: string) {
35	  const b = spec.requirements.bands.find((x) => x.id === id);
36	  if (!b) throw new Error(`unknown band ${id}`);
37	  return b;
38	}
39	
40	function resultFor(run: Run, cand: Candidate): SimResult {
41	  const key = `${run.id}::${cand.candidate_id}`;
42	  const cached = resultCache.get(key);
43	  if (cached) return cached;
44	  const r = simulate(run.spec, bandById(run.spec, cand.band_id), cand);
45	  resultCache.set(key, r);
46	  return r;
47	}
48	
49	/** Client-side constraint edits are applied to a per-run copy of the spec. */
50	export function applyOverrides(
51	  overrides: RunOverrides | undefined,
52	): DeviceSpec {
53	  if (!overrides) return phoneV1;
54	  return {
55	    ...phoneV1,
56	    requirements: {
57	      ...phoneV1.requirements,
58	      sar_limit: overrides.sar_limit ?? phoneV1.requirements.sar_limit,
59	      bands: phoneV1.requirements.bands.map((b) => ({
60	        ...b,
61	        ...(overrides.bands?.[b.id] ?? {}),
62	      })),
63	    },
64	  };
65	}
66	
67	export interface RunOverrides {
68	  sar_limit?: DeviceSpec["requirements"]["sar_limit"];
69	  bands?: Record<string, Partial<BandRequirement>>;
70	}
71	
72	export function createRun(
73	  prompt: string,
74	  bandIds: string[],
75	  perBand = 6,
76	  overrides?: RunOverrides,
77	): { runId: string; candidates: Candidate[] } {
78	  const spec = applyOverrides(overrides);
79	  const all = generateCandidates(spec, bandIds);
80	  const perBandTop = bandIds.map((bandId) =>
81	    all
82	      .filter((c) => c.band_id === bandId)
83	      .sort((a, b) => b.prior - a.prior)
84	      .slice(0, perBand),
85	  );
86	  // Interleave bands so early results cover the whole system, not one band.
87	  const queue: Candidate[] = [];
88	  for (let i = 0; i < perBand; i++) {
89	    for (const list of perBandTop) if (list[i]) queue.push(list[i]);
90	  }
91	
92	  const id = `run_${Date.now().toString(36)}`;
93	  runs.set(id, {
94	    id,
95	    prompt,
96	    bandIds,
97	    createdAt: Date.now(),
98	    spec,
99	    candidates: all,
100	    queue,
101	  });
102	  return { runId: id, candidates: all };
103	}
104	
105	function jobStates(run: Run, now: number): Job[] {
106	  return run.queue.map((c, i) => {
107	    const start = run.createdAt + PLANNING_MS + Math.floor(i / CONCURRENCY) * PER_JOB_MS;
108	    const end = start + PER_JOB_MS;
109	    let status: Job["status"] = "queued";
110	    let progress = 0;
111	    if (now >= end) {
112	      status = "complete";
113	      progress = 1;
114	    } else if (now >= start) {
115	      status = "running";
116	      progress = (now - start) / PER_JOB_MS;
117	    }
118	    return {
119	      job_id: `${run.id}__${c.candidate_id}`,
120	      candidate_id: c.candidate_id,
121	      band_id: c.band_id,
122	      status,
123	      progress: +progress.toFixed(3),
124	      started_at: now >= start ? start : undefined,
125	      finished_at: now >= end ? end : undefined,
126	    };
127	  });
128	}
129	
130	export interface RunSnapshot {
131	  runId: string;
132	  done: boolean;
133	  planning: boolean;
134	  jobs: Job[];
135	  results: Record<string, SimResult>;
136	  candidates: Candidate[];
137	  messages: AgentMessage[];
138	  placements: Record<string, string>;
139	  isolation: { a: string; b: string; db: number }[];
140	}
141	
142	export function readRun(runId: string): RunSnapshot | null {
143	  const run = runs.get(runId);
144	  if (!run) return null;
145	  const now = Date.now();
146	  const jobs = jobStates(run, now);
147	  const planning = now < run.createdAt + PLANNING_MS;
148	  const done = jobs.every((j) => j.status === "complete");
149	
150	  const results: Record<string, SimResult> = {};
151	  for (const j of jobs) {
152	    const cand = run.queue.find((c) => c.candidate_id === j.candidate_id)!;
153	    if (j.status === "complete") results[j.candidate_id] = resultFor(run, cand);
154	    else
155	      results[j.candidate_id] = {
156	        ...emptyResult(j.candidate_id),
157	        status: j.status,
158	      };
159	  }
160	
161	  const { placements, relocations } = assign(run, jobs, results);
162	
163	  const isolation: { a: string; b: string; db: number }[] = [];
164	  const placed = Object.entries(placements);
165	  for (let i = 0; i < placed.length; i++) {
166	    for (let k = i + 1; k < placed.length; k++) {
167	      const ca = run.queue.find((c) => c.candidate_id === placed[i][1])!;
168	      const cb = run.queue.find((c) => c.candidate_id === placed[k][1])!;
169	      const ba = bandById(run.spec, ca.band_id);
170	      const bb = bandById(run.spec, cb.band_id);
171	      isolation.push({
172	        a: ca.candidate_id,
173	        b: cb.candidate_id,
174	        db: isolationDb(
175	          ca.position_mm,
176	          cb.position_mm,
177	          (ba.f_low_ghz + ba.f_high_ghz) / 2,
178	          (bb.f_low_ghz + bb.f_high_ghz) / 2,
179	        ),
180	      });
181	    }
182	  }
183	
184	  return {
185	    runId: run.id,
186	    done,
187	    planning,
188	    jobs,
189	    results,
190	    candidates: run.candidates,
191	    messages: buildMessages(
192	      run,
193	      jobs,
194	      results,
195	      placements,
196	      isolation,
197	      relocations,
198	      planning,
199	      done,
200	    ),
201	    placements,
202	    isolation,
203	  };
204	}
205	
206	/**
207	 * One antenna per band, each on its own anchor. Bands are assigned
208	 * lowest-frequency first because they are the most clearance-hungry, and a
209	 * candidate is skipped when it couples too strongly into an already-placed
210	 * antenna or reuses an occupied anchor.
211	 */
212	function assign(run: Run, jobs: Job[], results: Record<string, SimResult>) {
213	  const placements: Record<string, string> = {};
214	  const relocations: { band_id: string; from: string; to: string; why: string }[] =
215	    [];
216	  const taken: Candidate[] = [];
217	
218	  const order = run.bandIds
219	    .slice()
220	    .sort(
221	      (a, b) =>
222	        bandById(run.spec, a).f_low_ghz - bandById(run.spec, b).f_low_ghz,
223	    );
224	
225	  for (const bandId of order) {
226	    const band = bandById(run.spec, bandId);
227	    const fc = (band.f_low_ghz + band.f_high_ghz) / 2;
228	    const ranked = jobs
229	      .filter((j) => j.band_id === bandId && j.status === "complete")
230	      .map((j) => run.queue.find((c) => c.candidate_id === j.candidate_id)!)
231	      .filter(Boolean)
232	      .sort((a, b) => rank(results[b.candidate_id]) - rank(results[a.candidate_id]));
233	    if (!ranked.length) continue;
234	
235	    let chosen: Candidate | undefined;
236	    let reason = "";
237	    for (const cand of ranked) {
238	      if (taken.some((t) => t.anchor_id === cand.anchor_id)) {
239	        reason = reason || `${cand.anchor_id} already occupied`;
240	        continue;
241	      }
242	      const worst = taken.reduce((acc, t) => {
243	        const tb = bandById(run.spec, t.band_id);
244	        const db = isolationDb(
245	          cand.position_mm,
246	          t.position_mm,
247	          fc,
248	          (tb.f_low_ghz + tb.f_high_ghz) / 2,
249	        );
250	        return Math.max(acc, db);
251	      }, -99);
252	      if (worst > run.spec.requirements.isolation_db_max) {
253	        reason =
254	          reason ||
255	          `${cand.anchor_id} would only give ${worst.toFixed(1)} dB isolation`;
256	        continue;
257	      }
258	      chosen = cand;
259	      break;
260	    }
261	
262	    if (!chosen) chosen = ranked[0];
263	    if (chosen.candidate_id !== ranked[0].candidate_id) {
264	      relocations.push({
265	        band_id: bandId,
266	        from: ranked[0].anchor_id,
267	        to: chosen.anchor_id,
268	        why: reason,
269	      });
270	    }
271	    placements[bandId] = chosen.candidate_id;
272	    taken.push(chosen);
273	  }
274	
275	  return { placements, relocations };
276	}
277	
278	/** Composite ranking used to pick the winner per band. */
279	export function rank(r: SimResult) {
280	  return (
281	    (r.meets_requirements ? 1 : 0) * 2 +
282	    Math.min(-r.s11_min_db / 20, 1) +
283	    r.efficiency +
284	    Math.min(r.bandwidth_mhz / 600, 1) * 0.5
285	  );
286	}
287	
288	function emptyResult(id: string): SimResult {
289	  return {
290	    candidate_id: id,
291	    status: "queued",
292	    runtime_s: 0,
293	    s11_curve: [],
294	    s11_min_db: 0,
295	    resonant_ghz: 0,
296	    bandwidth_mhz: 0,
297	    efficiency: 0,
298	    peak_gain_dbi: 0,
299	    vswr: 0,
300	    sar_w_per_kg: 0,
301	    meets_requirements: false,
302	    notes: "",
303	  };
304	}
305	
306	function buildMessages(
307	  run: Run,
308	  jobs: Job[],
309	  results: Record<string, SimResult>,
310	  placements: Record<string, string>,
311	  isolation: { a: string; b: string; db: number }[],
312	  relocations: { band_id: string; from: string; to: string; why: string }[],
313	  planning: boolean,
314	  done: boolean,
315	): AgentMessage[] {
316	  const m: AgentMessage[] = [];
317	  const spec = run.spec;
318	  let t = run.createdAt;
319	  const push = (kind: AgentMessage["kind"], text: string) =>
320	    m.push({ id: `m${m.length}`, role: "agent", kind, text, ts: (t += 1) });
321	
322	  push(
323	    "text",
324	    `Reading ${spec.name}. ${spec.components.length} named components, ` +
325	      `board ${spec.board.size_mm.join(" x ")} mm on ${spec.board.stackup} ` +
326	      `(er ${spec.board.epsilon_r}, tan-d ${spec.board.loss_tangent}).`,
327	  );
328	  push(
329	    "step",
330	    `Metal and lossy blocks that constrain placement: ` +
331	      `battery, camera module, PCB ground plane, taptic engine, loudspeaker. ` +
332	      `Enclosure back is glass (er 5.5), frame is aluminium and is treated as a radiator, not a blocker.`,
333	  );
334	
335	  for (const bandId of run.bandIds) {
336	    const band = bandById(spec, bandId);
337	    const top = run.queue.filter((c) => c.band_id === bandId);
338	    push(
339	      "step",
340	      `${band.name} (${band.f_low_ghz}-${band.f_high_ghz} GHz) needs >= ${band.clearance_mm} mm clearance. ` +
341	        `Shortlisted ${top.length} anchors, best prior at ${top[0]?.rationale ?? "n/a"}.`,
342	    );
343	  }
344	
345	  if (planning) return m;
346	
347	  for (const j of jobs) {
348	    const cand = run.queue.find((c) => c.candidate_id === j.candidate_id)!;
349	    const band = bandById(spec, j.band_id);
350	    if (j.status === "running") {
351	      push(
352	        "step",
353	        `Running FDTD sweep for ${cand.candidate_id} (${cand.antenna_type}, ${band.name}) at ${cand.position_mm.map((v) => v.toFixed(0)).join(", ")} mm.`,
354	      );
355	    } else if (j.status === "complete") {
356	      const r = results[j.candidate_id];
357	      push(
358	        "result",
359	        `${cand.candidate_id}: S11 ${r.s11_min_db.toFixed(1)} dB at ${r.resonant_ghz.toFixed(2)} GHz, ` +
360	          `BW ${r.bandwidth_mhz} MHz, eff ${(r.efficiency * 100).toFixed(0)}%, gain ${r.peak_gain_dbi} dBi, ` +
361	          `SAR ${r.sar_w_per_kg} W/kg -> ${r.meets_requirements ? "PASS" : "FAIL"}. ${r.notes}`,
362	      );
363	    }
364	  }
365	
366	  if (done) {
367	    for (const r of relocations) {
368	      const band = bandById(spec, r.band_id);
369	      push(
370	        "step",
371	        `${band.name}: best-scoring anchor was ${r.from}, but ${r.why}. Moved to ${r.to}.`,
372	      );
373	    }
374	    for (const [bandId, candId] of Object.entries(placements)) {
375	      const cand = run.queue.find((c) => c.candidate_id === candId)!;
376	      const band = bandById(spec, bandId);
377	      const s = scorePoint(spec, band, cand.position_mm);
378	      push(
379	        "text",
380	        `Recommendation for ${band.name}: ${cand.antenna_type} at ${cand.position_mm.map((v) => v.toFixed(1)).join(", ")} mm, ` +
381	          `radiator length ${cand.length_mm} mm, feed at ${cand.feed_point_mm.map((v) => v.toFixed(1)).join(", ")} mm. ` +
382	          `Keep-out ${band.clearance_mm} mm; nearest blocker is ${s.blocker} at ${s.clearance_mm.toFixed(1)} mm.`,
383	      );
384	    }
385	    const worst = isolation.slice().sort((a, b) => b.db - a.db)[0];
386	    if (worst) {
387	      push(
388	        "text",
389	        `Worst-case isolation between placed antennas is ${worst.db} dB (${worst.a} / ${worst.b}); ` +
